   "Built for release timing, destination coordination, family communication, and medically oriented transport planning after discharge.":"Conçu pour le calendrier de sortie, la coordination de la destination, la communication avec la famille et la planification de transport à orientation médicale après la sortie d’hôpital.",
   "Built for repeat appointment travel, passenger routines, and dependable coordination for ongoing treatment schedules.":"Conçu pour les déplacements répétés aux rendez-vous, les habitudes des passagers et une coordination fiable pour les calendriers de traitement en cours.",
   "Busiest days of the week":"Jours de la semaine les plus chargés",
