   "button compact":"button compact",
   "button compact secondary":"button compact secondary",
   "button secondary":"button secondary",
   "By providing a mobile number through a disclosed Nexus booking or enrollment flow, you agree to receive transactional booking and ride updates. Message frequency varies and message and data rates may apply. Reply STOP to end texts and HELP for assistance. Stopping messages may limit real-time trip updates but does not cancel a scheduled trip. Call Customer Service to change communication preferences or cancel transportation. Consent is not a condition of purchase.":"En fournissant un numéro de mobile via un parcours de réservation ou d’inscription Nexus divulgué, vous acceptez de recevoir des mises à jour transactionnelles sur la réservation et le trajet. La fréquence des messages varie et des frais de messagerie et de données peuvent s’appliquer. Répondez STOP pour mettre fin aux textos et HELP pour obtenir de l’aide. L’arrêt des messages peut limiter les mises à jour de trajet en temps réel, mais n’annule pas un trajet planifié. Appelez le service client pour modifier vos préférences de communication ou annuler un transport. Le consentement n’est pas une condition d’achat.",
   "By providing your number and continuing, you agree to receive transactional booking and ride texts from Nexus Medical Transit, including one reminder if an unfinished booking is inactive for five minutes. Message frequency varies. Message and data rates may apply. Reply HELP for help or STOP to opt out. Consent is not a condition of purchase.":"En fournissant votre numéro et en continuant, vous acceptez de recevoir des textos transactionnels de réservation et de trajet de Nexus Medical Transit, y notamment un rappel si une réservation inachevée est inactive pendant cinq minutes. La fréquence des messages varie. Des frais de messagerie et de données peuvent s’appliquer. Répondez HELP pour obtenir de l’aide ou STOP pour vous désinscrire. Le consentement n’est pas une condition d’achat.",
   "By submitting, you authorize Nexus Medical Transit to contact you about employment opportunities. Information is used for recruiting and hiring purposes.":"En soumettant, vous autorisez Nexus Medical Transit à vous contacter au sujet d’opportunités d’emploi. Les informations sont utilisées à des fins de recrutement et d’embauche.",
   "calc(10% - 12px)":"calc(10% - 12px)",
