   "Calculated from the route and appointment time.":"Calculé à partir de l’itinéraire et de l’heure du rendez-vous.",
   "Calculated to arrive by your required time.":"Calculé pour arriver à l’heure requise.",
   "Calculated to get you to your appointment on time.":"Calculé pour vous amener à votre rendez-vous à l’heure.",
   "Calculating prices...":"Calcul des prix...",
