   "Common long-distance trips include appointments at hospitals and specialists in other states, hospital discharge rides to family in another state, interfacility transfers, and trips that start and end outside the local region entirely. If the care your passenger needs is in another state, we can plan the ride around it.":"Les trajets longue distance courants comprennent les rendez-vous dans des hôpitaux et chez des spécialistes dans d’autres États, les trajets de sortie d’hôpital vers la famille dans un autre État, les transferts entre établissements, et les trajets qui commencent et se terminent entièrement en dehors de la région locale. Si les soins dont votre passager a besoin se trouvent dans un autre État, nous pouvons planifier le trajet en conséquence.",
