   "Communications may include booking confirmations, driver or vehicle details, pickup status, delays, cancellations, recurring-trip reminders, account security, payment, support, and safety information. Message frequency varies. Carrier message and data rates may apply.":"Les communications peuvent inclure les confirmations de réservation, les informations sur le chauffeur ou le véhicule, le statut de la prise en charge, les retards, les annulations, les rappels de trajets récurrents, la sécurité du compte, le paiement, l’assistance et les informations de sécurité. La fréquence des messages varie. Les tarifs de messagerie et de données de l’opérateur peuvent s’appliquer.",
   "Communications Terms":"Conditions de communication",
