   "Compare the configured allowance with recent completed patient trips. Driving includes traffic stops; boarding and handoff are measured separately. These fleet averages support analysis; each booking continues to use its own route and schedule.":"Comparez l’indemnité configurée avec les trajets patients terminés récemment. La conduite inclut les arrêts de circulation ; l’embarquement et le transfert sont mesurés séparément. Ces moyennes de flotte facilitent l’analyse ; chaque réservation continue d’utiliser son propre itinéraire et son propre horaire.",
