   "Day-to-day service covers Maryland, Washington, DC, and Virginia. Nexus also provides interstate and long-distance transportation to the other 46 contiguous states for trips planned in advance — Alaska, Hawaii, and international trips are not served. See our Maryland, DC, and Northern Virginia pages for local detail, or our":"Le service quotidien couvre le Maryland, Washington, DC et la Virginie. Nexus fournit également des transports inter-États et longue distance vers les 46 autres États contigus pour les trajets planifiés à l’avance — Alaska, Hawaii et les trajets internationaux ne sont pas desservis. Consultez nos pages Maryland, DC et Virginie du Nord pour les détails locaux, ou notre",
