   "Dialysis & recurring rides":"Dialyse et trajets récurrents",
   "Dialysis and recurring care rides":"Trajets de dialyse et de soins récurrents",
   "Dialysis and recurring therapy trips":"Trajets de dialyse et de thérapie récurrente",
