   "Dialysis Center":"Centre de dialyse",
   "Dialysis centers, rehabilitation, and skilled nursing facilities":"Centres de dialyse, réadaptation et établissements de soins infirmiers qualifiés",
   "Dialysis often starts early. Many treatment shifts begin in the early morning, so Nexus builds early morning pickups into recurring schedules in advance — timed to your center's start time, so you arrive settled rather than rushed. Regular hours are Monday–Friday, 7 AM–7 PM, and earlier pickups are arranged by appointment when your schedule is set up.":"La dialyse commence souvent tôt. De nombreux quarts de traitement débutent tôt le matin, c’est pourquoi Nexus intègre à l’avance des prises en charge tôt le matin dans les horaires récurrents — programmées selon l’heure de début de votre centre, pour que vous arriviez détendu plutôt que pressé. Les heures habituelles sont du lundi au vendredi, de 7 h à 19 h, et des prises en charge plus tôt sont organisées sur rendez-vous lors de la mise en place de votre horaire.",
   "Dialysis several times a week":"Dialyse plusieurs fois par semaine",
   "Dialysis transportation":"Transport pour dialyse",
   "Dialysis Transportation | Nexus Medical Transit":"Transport pour la dialyse | Nexus Medical Transit",
   "Dialysis transportation is coordinated across Maryland, Washington, DC, and Northern Virginia based on trip details and operational availability. For longer trips, Nexus also provides interstate and long-distance transportation across the contiguous United States, scheduled in advance.":"Le transport pour dialyse est coordonné dans le Maryland, Washington, DC et le nord de la Virginie en fonction des détails du trajet et de la disponibilité opérationnelle. Pour les trajets plus longs, Nexus fournit également des transports inter-États et longue distance dans l’ensemble des États-Unis contigus, planifiés à l’avance.",
   "Dialysis transportation page":"Page du transport pour dialyse",
   "Dialysis transportation with dependable scheduling and repeat-trip coordination.":"Transport pour dialyse avec une planification fiable et une coordination des trajets répétés.",
   "Discharge and transfer coordination for Annapolis-area facilities, with LiveCare tracking for families from pickup to arrival.":"Coordination des sorties et des transferts pour les établissements de la région d’Annapolis, avec suivi LiveCare pour les familles de la prise en charge à l’arrivée.",
   "Discharge coordination":"Coordination des sorties",
   "Discharge home for patients who cannot ride seated":"Retour à domicile après la sortie pour les patients qui ne peuvent pas voyager assis",
   "Discharge planning and return-home transportation":"Planification de la sortie et transport de retour à domicile",
   "Discharge travel works best when pickup timing, passenger mobility, destination, and handoff are coordinated clearly before release.":"Le transport de sortie fonctionne mieux lorsque l’heure de prise en charge, la mobilité du passager, la destination et le transfert sont coordonnés clairement avant la sortie.",
   "Discount applied: $":"Remise appliquée : $",
   "Dismiss reminder":"Ignorer le rappel",
   "DISPATCH":"RÉPARTITION",
   "Dispatch assigning your driver":"La répartition affecte votre chauffeur",
   "Dispatch Center | NEXUS ONE":"Centre de répartition | NEXUS ONE",
   "Dispatch dashboard sections":"Sections du tableau de bord de répartition",
   "Dispatch fleet telemetry":"Télémétrie de la flotte de répartition",
   "Dispatch intake hub":"Centre d’admission de la répartition",
   "Dispatch overhead per trip ($)":"Frais généraux de répartition par trajet ($)",
   "Dispatch sign in":"Connexion à la répartition",
   "Dispatch will confirm and finalize your trip shortly.":"La répartition confirmera et finalisera votre trajet sous peu.",
   "Dispatch will contact you shortly to finalize payment.":"La répartition vous contactera sous peu pour finaliser le paiement.",
   "Dispatch workspace":"Espace de travail de répartition",
   "Dispatch-entered bookings send the passenger a secure payment link before pickup.":"Les réservations saisies par la répartition envoient au passager un lien de paiement sécurisé avant la prise en charge.",
   "DISPATCHED":"DÉPÊCHÉ",
   "DISPATCHER":"RÉPARTITEUR",
   "Distance & ETA":"Distance et heure d’arrivée",
   "Do not enter patient names, diagnoses, medical records, payment details, or other sensitive personal information here. Questions are sent to the Nexus assistant service to generate a response. The public assistant uses a small amount of conversation history kept in this page's memory to understand follow-up questions. Reloading or closing the page clears it; this page does not save chat history to browser storage.":"Ne saisissez pas ici de noms de patients, de diagnostics, de dossiers médicaux, de détails de paiement ni d’autres informations personnelles sensibles. Les questions sont envoyées au service d’assistance Nexus pour générer une réponse. L’assistant public utilise une petite partie de l’historique de conversation conservé dans la mémoire de cette page pour comprendre les questions de suivi. Recharger ou fermer la page l’efface ; cette page n’enregistre pas l’historique de discussion dans le stockage du navigateur.",
   "Do not fill this out:":"Ne remplissez pas ceci :",
   "Do not send Social Security or financial information.":"N’envoyez pas d’informations de sécurité sociale ou financières.",
   "Do not upload driver licenses, government IDs, insurance certificates, or patient records here. Nexus will request supporting credentials through its secure verification process.":"Ne téléversez pas ici de permis de conduire, de pièces d’identité gouvernementales, de certificats d’assurance ou de dossiers de patients. Nexus demandera les justificatifs à l’appui via son processus de vérification sécurisé.",
   "Do not use a privacy request or email to seek urgent transportation or medical assistance. For a medical emergency, call 911. For an active trip, call Customer Service.":"N’utilisez pas une demande de confidentialité ou un courriel pour demander un transport urgent ou une assistance médicale. En cas d’urgence médicale, appelez le 911. Pour un trajet en cours, appelez le Service client.",
   "Do you offer bariatric transportation near me?":"Proposez-vous un transport bariatrique près de chez moi ?",
   "Do you offer early morning pickups for surgery, dialysis, or early appointments?":"Proposez-vous des prises en charge tôt le matin pour une intervention chirurgicale, une dialyse ou des rendez-vous tôt ?",
   "Do you offer transportation to other states?":"Proposez-vous des transports vers d’autres États ?",
   "Do you run trips from Annapolis to DC or Baltimore hospitals?":"Effectuez-vous des trajets d’Annapolis vers les hôpitaux de DC ou de Baltimore ?",
   "Do you serve addresses outside the county line?":"Desservez-vous des adresses en dehors des limites du comté ?",
   "Do you serve Alaska, Hawaii, or other countries?":"Desservez-vous Alaska, Hawaii ou d’autres pays ?",
   "Do you want to know what your ride would cost?":"Voulez-vous savoir combien coûterait votre trajet ?",
