   "Enter each appointment time. Pickup and waiting at each stop are calculated from the next appointment. We include travel, traffic, and passenger assistance to check whether one driver can make every appointment.":"Saisissez chaque heure de rendez-vous. La prise en charge et l’attente à chaque arrêt sont calculées à partir du rendez-vous suivant. Nous incluons le déplacement, la circulation et l’assistance au passager pour vérifier si un seul chauffeur peut se rendre à chaque rendez-vous.",
