   "Enter starting odometer, then start auto log. The app will detect arrival/departure and log route mileage.":"Saisissez le compteur kilométrique de départ, puis démarrez l’enregistrement automatique. L’application détectera l’arrivée/le départ et enregistrera le kilométrage de l’itinéraire.",
