   "Hospital discharge transportation":"Transport pour sortie d’hôpital",
   "Hospital Discharge Transportation | Nexus Medical Transit":"Transport pour sortie d’hôpital | Nexus Medical Transit",
   "Hospital discharge transportation is coordinated across Maryland, Washington, DC, and Northern Virginia based on facility location, passenger needs, and route availability. For longer trips — including discharge to family in another state — Nexus also provides interstate and long-distance transportation across the contiguous United States, scheduled in advance.":"Le transport pour sortie d’hôpital est coordonné dans le Maryland, Washington, DC et le nord de la Virginie en fonction de l’emplacement de l’établissement, des besoins du passager et de la disponibilité des itinéraires. Pour les trajets plus longs — y compris la sortie vers la famille dans un autre État — Nexus fournit également des transports inter-États et longue distance dans l’ensemble des États-Unis contigus, planifiés à l’avance.",
   "Hospital discharge transportation planned around the passenger, caregiver, and release timeline.":"Transport pour sortie d’hôpital planifié en fonction du passager, de l’aidant et du calendrier de sortie.",
