   "I am authorized to arrange transportation for this patient and save these details.":"Je suis autorisé à organiser le transport pour ce patient et à enregistrer ces détails.",
   "I am legally authorized to work in the United States. *":"Je suis légalement autorisé à travailler aux États-Unis. *",
   "I can show you how to use the app and explain Nexus when you want more detail.":"Je peux vous montrer comment utiliser l’application et vous expliquer Nexus lorsque vous souhaitez plus de détails.",
   "I can work out a rough estimate right here — no need to open the booking app first. I just need a few details. (Availability itself is confirmed when you book.)":"Je peux calculer une estimation approximative ici même — pas besoin d’ouvrir d’abord l’application de réservation. J’ai juste besoin de quelques détails. (La disponibilité elle-même est confirmée lors de la réservation.)",
   "I can’t reach the assistant right now. Please call us at":"Je ne peux pas joindre l’assistant pour le moment. Veuillez nous appeler au",
   "I certify that the information provided is true and complete to the best of my knowledge. I understand that false statements may disqualify me from consideration or employment. *":"Je certifie que les informations fournies sont vraies et complètes au meilleur de ma connaissance. Je comprends que de fausses déclarations peuvent me disqualifier de la considération ou de l’emploi. *",
   "I could not connect to the Nexus estimate service.":"Je n’ai pas pu me connecter au service d’estimation de Nexus.",
