   "Identify passengers and users, coordinate trips, communicate, prevent fraud":"Identifier les passagers et les utilisateurs, coordonner les trajets, communiquer, prévenir la fraude",
   "Identify transportation barriers early, coordinate the right intervention, and verify whether patients reach care.":"Identifier tôt les obstacles au transport, coordonner la bonne intervention et vérifier si les patients accèdent aux soins.",
   "Identity and contact":"Identité et contact",
   "If an account exists, a reset link has been sent.":"Si un compte existe, un lien de réinitialisation a été envoyé.",
   "If no report arrives for more than 15 minutes, monitoring is marked stale. If the database or hosting platform is down, this monitor may also be unavailable.":"Si aucun rapport n’arrive pendant plus de 15 minutes, la surveillance est marquée comme obsolète. Si la base de données ou la plateforme d’hébergement est en panne, ce moniteur peut également être indisponible.",
   "If you are experiencing a medical emergency, call 911 immediately.":"Si vous vivez une urgence médicale, appelez le 911 immédiatement.",
   "If your health plan, provider, facility, or broker arranged the transportation, it may be the best first contact for a HIPAA access, amendment, restriction, or accounting request. Nexus will route or support requests as required. Verification of identity and authority may be required before information is released.":"Si votre régime de santé, votre prestataire, votre établissement ou votre courtier a organisé le transport, il peut être le meilleur premier contact pour une demande d’accès, de modification, de restriction ou de comptabilisation au titre de la HIPAA. Nexus transmettra ou appuiera les demandes selon les exigences. Une vérification de l’identité et de l’autorité peut être requise avant la divulgation d’informations.",
