   "Inferences reasonably necessary to select or coordinate an appropriate transportation service.":"Inférences raisonnablement nécessaires pour sélectionner ou coordonner un service de transport approprié.",
   "Information another authorized person provides when arranging a trip.":"Informations qu’une autre personne autorisée fournit lors de l’organisation d’un trajet.",
   "Information is retained for as long as reasonably necessary for transportation, safety, billing, legal, contractual, audit, dispute-resolution, and recordkeeping purposes. Retention varies by record type and applicable requirements. When information is no longer required, Nexus takes reasonable steps to delete, destroy, or de-identify it.":"Les informations sont conservées aussi longtemps que raisonnablement nécessaire à des fins de transport, de sécurité, de facturation, juridiques, contractuelles, d’audit, de résolution de litiges et de tenue de dossiers. La conservation varie selon le type de dossier et les exigences applicables. Lorsque les informations ne sont plus requises, Nexus prend des mesures raisonnables pour les supprimer, les détruire ou les dépersonnaliser.",
   "Information may come directly from you or from an authorized caregiver, facility, healthcare provider, health plan, broker, government program, transportation provider, driver, payment processor, communications provider, or other party involved in arranging or delivering a trip.":"Les informations peuvent provenir directement de vous ou d’un aidant autorisé, d’un établissement, d’un prestataire de soins de santé, d’un régime de santé, d’un courtier, d’un programme gouvernemental, d’un prestataire de transport, d’un chauffeur, d’un processeur de paiement, d’un prestataire de communications ou d’une autre partie impliquée dans l’organisation ou la réalisation d’un trajet.",
