   "Is this emergency ambulance service?":"S’agit-il d’un service d’ambulance d’urgence ?",
   "Is this intended for emergencies?":"Est-ce destiné aux urgences ?",
   "Issues appear here after two failed checks and clear when a check passes. Acknowledging an issue records that it has been seen; it does not repair it. No code or production records are changed. AI recommendations require an API connection and human review.":"Les problèmes apparaissent ici après deux vérifications échouées et disparaissent lorsqu’une vérification réussit. Accuser réception d’un problème enregistre qu’il a été vu ; cela ne le répare pas. Aucun code ni aucun dossier de production n’est modifié. Les recommandations de l’IA nécessitent une connexion API et un examen humain.",
