   "Johns Hopkins Health Plans":"Johns Hopkins Health Plans",
   "Join a team that connects patients with essential care across Maryland, Washington, DC, and Northern Virginia. We value safety, compassion, accountability, and respect in every role.":"Rejoignez une équipe qui relie les patients à des soins essentiels dans le Maryland, Washington, DC et le nord de la Virginie. Nous valorisons la sécurité, la compassion, la responsabilité et le respect dans chaque rôle.",
