   "Keep credentials confidential, use only the access assigned to you, and notify Nexus of suspected unauthorized access. Facility, driver, dispatcher, billing, and administrative portals may only be used for authorized business purposes. Users may not scrape data, probe security, disrupt service, impersonate another person, or access records without a legitimate need.":"Gardez vos identifiants confidentiels, utilisez uniquement l'accès qui vous est attribué et informez Nexus en cas de suspicion d'accès non autorisé. Les portails des établissements, des chauffeurs, des répartiteurs, de la facturation et de l'administration ne peuvent être utilisés qu'à des fins professionnelles autorisées. Les utilisateurs ne peuvent pas extraire de données, tester la sécurité, perturber le service, usurper l'identité d'une autre personne ou accéder à des dossiers sans besoin légitime.",
   "Keep current schedule":"Conserver l'horaire actuel",
