   "MANUAL":"MANUAL",
   "Manual override":"Remplacement manuel",
   "Many surgeries, dialysis treatments, and clinic appointments start early — often before regular hours. Nexus schedules early morning pickups in advance, timed around your check-in or treatment time, so the right vehicle and crew are matched to the trip before the day begins. Our regular hours are Monday–Friday, 7 AM–7 PM, and early pickups are arranged by appointment when you book ahead.":"De nombreuses interventions chirurgicales, traitements de dialyse et rendez-vous en clinique commencent tôt — souvent avant les heures régulières. Nexus planifie à l'avance les prises en charge tôt le matin, en fonction de votre heure d'enregistrement ou de traitement, afin que le véhicule et l'équipe adaptés soient affectés au trajet avant le début de la journée. Nos heures régulières sont du lundi au vendredi, de 7 h à 19 h, et les prises en charge tôt le matin sont organisées sur rendez-vous lorsque vous réservez à l'avance.",
