   "Mock trips and incomplete driving or GPS records are excluded. Thirty separate trips is an initial review target; route mix, traffic and patient needs still need comparison. This report does not change any speed or fare setting.":"Les trajets fictifs et les dossiers de conduite ou GPS incomplets sont exclus. Trente trajets distincts constituent un objectif d’examen initial ; la composition des itinéraires, la circulation et les besoins des patients doivent encore être comparés. Ce rapport ne modifie aucun réglage de vitesse ou de tarif.",
   "Mock trips appear in Trip Management under Mock Trips. They do not request transport or collect payment.":"Les trajets fictifs apparaissent dans Gestion des trajets sous Trajets fictifs. Ils ne demandent pas de transport et ne collectent pas de paiement.",
