   "Need this same ride on more than one day? Add each extra service date — same pickup, route and times. One booking is created per date.":"Besoin de ce même trajet sur plus d’un jour ? Ajoutez chaque date de service supplémentaire — même prise en charge, même itinéraire et mêmes horaires. Une réservation est créée par date.",
   "Needs attention":"Nécessite une attention",
   "NEEDS_RIDE":"NEEDS_RIDE",
   "NEMT is planned transportation to healthcare — appointments, dialysis, therapy, discharge home, and facility transfers — for passengers who don't need emergency care but do need an accessible vehicle and assistance.":"Le NEMT est un transport planifié vers les soins de santé — rendez-vous, dialyse, thérapie, retour à domicile après une sortie et transferts entre établissements — pour les passagers qui n’ont pas besoin de soins d’urgence mais qui ont besoin d’un véhicule accessible et d’une assistance.",
