   "Nex autonomy health and review activity":"Santé de l’autonomie Nex et activité d’examen",
   "Nex can explain general services, accessible transportation, coverage, and how to request a ride.":"Nex peut expliquer les services généraux, le transport accessible, la zone desservie et comment demander un trajet.",
   "Nex cannot confirm a live ride booking or guarantee availability from this page.":"Nex ne peut pas confirmer une réservation de trajet en direct ni garantir la disponibilité depuis cette page.",
   "Nex Conversation Intelligence":"Nex Conversation Intelligence",
   "Nex does not diagnose conditions, recommend a patient's clinical level of transport, or provide emergency response.":"Nex ne diagnostique pas les affections, ne recommande pas le niveau clinique de transport d’un patient et ne fournit pas de réponse d’urgence.",
   "Nex Insights | Nexus Medical Transit":"Nex Insights | Nexus Medical Transit",
   "Nex integration readiness":"Préparation à l’intégration de Nex",
   "Nex knowledge approval workspace":"Espace de travail d’approbation des connaissances Nex",
   "Nex searches Nexus's approved website knowledge and uses that information to answer questions. Some responses may be phrased using an AI model; Nex also works using prewritten, retrieved answers when AI service is unavailable.":"Nex recherche dans les connaissances approuvées du site Web de Nexus et utilise ces informations pour répondre aux questions. Certaines réponses peuvent être formulées à l’aide d’un modèle d’IA ; Nex fonctionne également à l’aide de réponses préécrites et récupérées lorsque le service d’IA est indisponible.",
