   "No. Interstate service covers the 48 contiguous United States. Alaska, Hawaii, and anywhere outside the United States are out of area — for a trip entirely outside the contiguous states, a medical transport provider local to that area is the right call.":"Non. Le service inter-États couvre les 48 États contigus des États-Unis. Alaska, Hawaii et tout lieu en dehors des États-Unis sont hors zone — pour un trajet entièrement en dehors des États contigus, un prestataire de transport médical local à cette région est le bon choix.",
