   "of the Netlify environment variable that holds the value — names must start with KEYMARK_. The value itself stays in Netlify and is never stored in KeyMark. Saving with a name that already exists updates that connection. A new connection starts as “Configuration required” and becomes Active after its first successful test.":"de la variable d’environnement Netlify qui contient la valeur — les noms doivent commencer par KEYMARK_. La valeur elle-même reste dans Netlify et n’est jamais stockée dans KeyMark. Enregistrer avec un nom qui existe déjà met à jour cette connexion. Une nouvelle connexion commence comme “Configuration requise” et devient Active après son premier test réussi.",
