   "One coordinated NEMT workflow for passengers, caregivers, and facilities — with Livecare ride visibility when tracking is enabled.":"Un processus NEMT coordonné pour les passagers, les aidants et les établissements — avec la visibilité des trajets Livecare lorsque le suivi est activé.",
   "One identity can serve several roles. Classifications and business relationships do not grant account access. Sign-in accounts are managed separately, in each person's Account & access section — this page is the one place administrators manage people and their accounts.":"Une même identité peut remplir plusieurs rôles. Les classifications et les relations commerciales n’accordent pas l’accès au compte. Les comptes de connexion sont gérés séparément, dans la section Compte et accès de chaque personne — cette page est le seul endroit où les administrateurs gèrent les personnes et leurs comptes.",
