   "Passenger fare per leg = base + miles beyond the service allowance × per-mile rate + fuel + traffic overage. Apply one schedule premium per leg and its minimum fare. Then add waiting, deadhead and short notice, add card processing, and apply booking savings.":"Tarif passager par trajet = base + miles au-delà de l'allocation du service × tarif par mile + carburant + dépassement lié à la circulation. Appliquez un supplément d'horaire par trajet et son tarif minimum. Ajoutez ensuite l'attente, les miles à vide et le préavis court, ajoutez les frais de traitement par carte, et appliquez les économies de réservation.",
