   "Pickup means crew arrival. Loading, securement, unloading and patient handoff are included in the schedule for every leg. Starting allowances are planning assumptions; completed real trips refine facility estimates. Preparation is separate from billable waiting.":"Prise en charge signifie l'arrivée de l'équipe. Le chargement, l'arrimage, le déchargement et le transfert du patient sont inclus dans l'horaire de chaque trajet. Les allocations de départ sont des hypothèses de planification ; les trajets réels terminés affinent les estimations des établissements. La préparation est distincte de l'attente facturable.",
