   "Price depends on the trip itself — distance, ride type, required personnel and equipment, and timing — so there is no set fare. Book online at":"Le prix dépend du trajet lui-même — distance, type de trajet, personnel et équipement requis, et horaires — il n'y a donc pas de tarif fixe. Réservez en ligne sur",
   "Price estimates are based on information available when quoted and may change if mileage, wait time, tolls, service level, required personnel, equipment, or trip conditions change. Coverage or authorization by a health plan, government program, broker, facility, or other payer is not guaranteed. The responsible party remains responsible for charges not covered or authorized, to the extent permitted by law and contract.":"Les estimations de prix sont basées sur les informations disponibles au moment du devis et peuvent changer si le kilométrage, le temps d'attente, les péages, le niveau de service, le personnel requis, l'équipement ou les conditions du trajet changent. La couverture ou l'autorisation par un régime de santé, un programme gouvernemental, un courtier, un établissement ou un autre payeur n'est pas garantie. La partie responsable reste responsable des frais non couverts ou non autorisés, dans la mesure permise par la loi et le contrat.",
