   "Protocol *":"Protocole *",
   "Provide accurate passenger, pickup, destination, appointment, contact, mobility, equipment, assistance, and payer information.":"Fournissez des informations exactes sur le passager, la prise en charge, la destination, le rendez-vous, le contact, la mobilité, l'équipement, l'assistance et le payeur.",
   "Provide accurate trip and mobility information, use the service safely and lawfully, and contact us promptly when plans change. Nexus coordinates transportation; availability and arrival times can be affected by traffic, weather, clinical discharge timing, and other circumstances.":"Fournissez des informations exactes sur le trajet et la mobilité, utilisez le service de manière sûre et légale, et contactez-nous rapidement lorsque les plans changent. Nexus coordonne le transport ; la disponibilité et les heures d'arrivée peuvent être affectées par la circulation, la météo, le moment de la sortie clinique et d'autres circonstances.",
   "Provide safe, courteous transportation while completing vehicle checks, trip documentation, and patient handoffs.":"Fournissez un transport sûr et courtois tout en effectuant les vérifications du véhicule, la documentation du trajet et les transferts de patients.",
   "Provide support, document instructions, investigate incidents and improve quality":"Fournir un soutien, documenter les instructions, enquêter sur les incidents et améliorer la qualité",
   "Provider:":"Fournisseur :",
   "Public addresses are used for fictional trips only. Service eligibility, appointment availability and transport timings have not been confirmed.":"Les adresses publiques sont utilisées uniquement pour des trajets fictifs. L'admissibilité au service, la disponibilité des rendez-vous et les horaires de transport n'ont pas été confirmés.",
