   "Requested or estimated pickup and arrival times are not guarantees. Nexus is not responsible for delays or interruptions outside its reasonable control, including traffic, severe weather, road closures, facility delays, vehicle incidents, network failures, emergencies, labor interruptions, or government actions.":"Les heures de prise en charge et d’arrivée demandées ou estimées ne constituent pas des garanties. Nexus n’est pas responsable des retards ou interruptions hors de son contrôle raisonnable, y compris la circulation, les intempéries graves, les fermetures de routes, les retards d’établissement, les incidents de véhicule, les pannes de réseau, les urgences, les interruptions de travail ou les actions gouvernementales.",
