   "Review all system changes and user actions.":"Examinez toutes les modifications du système et les actions des utilisateurs.",
   "Review and confirm the fare estimate to continue to payment.":"Examinez et confirmez l’estimation du tarif pour passer au paiement.",
   "Review and confirm the fare estimate.":"Examinez et confirmez l’estimation du tarif.",
   "Review applications, résumés, hiring status, and applicant responses.":"Examinez les candidatures, les CV, le statut d’embauche et les réponses des candidats.",
   "Review career opportunities":"Voir les offres d’emploi",
   "Review every financial record before sending it to a payer or customer.":"Examinez chaque dossier financier avant de l’envoyer à un payeur ou à un client.",
