   "Review other options":"Voir d’autres options",
   "Review requests, assign drivers and vehicles, communicate with clients, and keep the Livecare timeline current from one operational workspace.":"Examinez les demandes, affectez les chauffeurs et les véhicules, communiquez avec les clients et maintenez la chronologie Livecare à jour depuis un seul espace de travail opérationnel.",
   "Review resources shared with your facility in one private, view-only workspace.":"Consultez les ressources partagées avec votre établissement dans un seul espace de travail privé, en lecture seule.",
   "Review the controlled Montgomery County prospect pilot and send a test.":"Examinez le projet pilote contrôlé de prospects du comté de Montgomery et envoyez un test.",
   "Review trip":"Examiner le trajet",
   "Review your phone number and email.":"Vérifiez votre numéro de téléphone et votre courriel.",
   "Review your shift summary before signing out. This data is submitted to Dispatch and Fleet.":"Examinez le résumé de votre quart avant de vous déconnecter. Ces données sont transmises à la Répartition et à la Flotte.",
   "Review-only suggestions based on anonymous aggregate counts. Nothing will be added to the knowledge base automatically. A minimum of three questions is required.":"Suggestions en lecture seule basées sur des comptages agrégés anonymes. Rien ne sera ajouté automatiquement à la base de connaissances. Un minimum de trois questions est requis.",
   "Reviewed October 2026. Recent research identifies road surface, suspension and smooth vehicle movement as factors in patient comfort; it does not establish fixed mph averages for each medical transport service. Wheelchair’s 10 mph deduction is a Nexus assumption. Securement, assisted loading and clinical handoff need their own time allowances.":"Révisé en octobre 2026. Des recherches récentes identifient l’état de la chaussée, la suspension et la fluidité des mouvements du véhicule comme des facteurs du confort des patients ; elles n’établissent pas de moyennes fixes en mi/h pour chaque service de transport médical. La déduction de 10 mi/h pour le fauteuil roulant est une hypothèse de Nexus. L’arrimage, le chargement assisté et le transfert clinique nécessitent leurs propres marges de temps.",
