   "Schedule premium (included)":"Supplément d’horaire (inclus)",
   "Schedule premium: Saturday and Sunday use the weekend rate; actual and observed federal holidays use the holiday rate. Weekday hours are 7:00 AM–7:00 PM. Each passenger leg receives one applicable premium on base fare, excess passenger mileage, fuel and traffic charges. Weekend takes priority, then holiday, then after hours. Waiting and empty miles are calculated separately.":"Supplément d’horaire : le samedi et le dimanche appliquent le tarif de week-end ; les jours fériés fédéraux réels et observés appliquent le tarif jour férié. Les horaires en semaine sont de 7:00 AM–7:00 PM. Chaque trajet passager reçoit un supplément applicable sur le tarif de base, le kilométrage passager excédentaire, les frais de carburant et de circulation. Le week-end a la priorité, puis le jour férié, puis les heures hors horaires. L’attente et les miles à vide sont calculés séparément.",
