   "Service reductions apply to a cruising-speed ceiling. With a 65 mph baseline, wheelchair uses 55 mph, stretcher 45 mph, ambulance services 40 mph and Bariatric 30 mph. Google city and traffic times remain the minimum estimate; reductions are not subtracted from slow city averages. These are Nexus planning assumptions.":"Les réductions de service s’appliquent à un plafond de vitesse de croisière. Avec une base de 65 mph, le fauteuil roulant utilise 55 mph, la civière 45 mph, les services d’ambulance 40 mph et le bariatrique 30 mph. Les temps Google en ville et dans la circulation restent l’estimation minimale ; les réductions ne sont pas soustraites des moyennes lentes en ville. Il s’agit d’hypothèses de planification de Nexus.",
