   "Some selected dates could not be booked. Check the booking message above for the dates that need attention.":"Certaines dates sélectionnées n'ont pas pu être réservées. Consultez le message de réservation ci-dessus pour les dates nécessitant une attention.",
   "Some trips do not fit inside one region. When a passenger needs care in another state — a specialist appointment, a hospital discharge to family, a transfer between facilities — Nexus Medical Transit plans the ride end to end: door-through-door support, the right vehicle and crew for the distance, and a pickup timed to the appointment. Day-to-day service runs locally in Maryland, Washington, DC, and Virginia; interstate trips cover the rest of the 48 contiguous states.":"Certains trajets ne se limitent pas à une seule région. Lorsqu'un passager a besoin de soins dans un autre État — un rendez-vous chez un spécialiste, une sortie d'hôpital vers la famille, un transfert entre établissements — Nexus Medical Transit planifie le trajet de bout en bout : assistance porte à porte, le véhicule et l'équipe adaptés à la distance, et une prise en charge synchronisée avec le rendez-vous. Le service quotidien est assuré localement dans le Maryland, à Washington, DC, et en Virginie ; les trajets inter-États couvrent le reste des 48 États contigus.",
   "Some trips, payments, maps, communications, or benefits may involve independent transportation providers or technology and payment vendors. Their services may be governed by additional terms. Nexus remains responsible for its own obligations but does not control every third party's independent acts.":"Certains trajets, paiements, cartes, communications ou avantages peuvent impliquer des prestataires de transport indépendants ou des fournisseurs de technologie et de paiement. Leurs services peuvent être régis par des conditions supplémentaires. Nexus reste responsable de ses propres obligations, mais ne contrôle pas les actes indépendants de chaque tiers.",
   "Something went wrong with that change — nothing was saved.":"Un problème est survenu avec cette modification — rien n'a été enregistré.",
