   "Special instructions, equipment needs, patient condition":"Instructions spéciales, besoins en équipement, état du patient",
   "Special protections for health-related and precise location data.":"Protections spéciales pour les données liées à la santé et de localisation précise.",
   "Specialty and follow-up appointments":"Rendez-vous de spécialité et de suivi",
   "Specialty and recurring treatment schedules":"Horaires de traitements spécialisés et récurrents",
   "Specialty appointments in Annapolis and into Baltimore, DC, and Montgomery County":"Rendez-vous de spécialité à Annapolis et vers Baltimore, DC et le comté de Montgomery",
   "Specialty appointments requiring monitoring en route":"Rendez-vous de spécialité nécessitant une surveillance en cours de route",
   "STAFF":"PERSONNEL",
   "Staff / administrator sign-in":"Connexion du personnel / administrateur",
   "Staff members":"Membres du personnel",
   "Standard vehicles don't fit every passenger, and a ride that starts with \"will it fit?\" starts wrong. Nexus plans bariatric transportation in advance: the right vehicle, the right equipment — higher-capacity wheelchair securement or stretcher — and a crew briefed on the pickup location, so there are no surprises at the door. Tell us the passenger's mobility equipment and any access details (steps, doorways, elevator) when you book, and we match the trip to it.":"Les véhicules standard ne conviennent pas à tous les passagers, et un trajet qui commence par « est-ce que ça va rentrer ? » commence mal. Nexus planifie le transport bariatrique à l'avance : le bon véhicule, le bon équipement — système de fixation pour fauteuil roulant de plus grande capacité ou civière — et une équipe informée du lieu de prise en charge, pour qu'il n'y ait aucune surprise à la porte. Indiquez-nous l'équipement de mobilité du passager et tout détail d'accès (marches, portes, ascenseur) lors de la réservation, et nous adapterons le trajet en conséquence.",
   "Start / restart LiveCare demo":"Démarrer / redémarrer la démo LiveCare",
   "Start / restart morning":"Démarrer / redémarrer la matinée",
   "Start a Maryland transportation request.":"Commencez une demande de transport dans le Maryland.",
   "Start a Montgomery County transportation request.":"Commencez une demande de transport dans le comté de Montgomery.",
   "Start a Northern Virginia transportation request.":"Commencez une demande de transport dans le nord de la Virginie.",
   "Start a request online or call our main public line for trip coordination and service guidance.":"Commencez une demande en ligne ou appelez notre ligne publique principale pour la coordination des trajets et des conseils sur le service.",
   "Start a stretcher booking":"Commencer une réservation en civière",
   "Start a transportation request now.":"Commencez une demande de transport dès maintenant.",
   "Start a Washington, DC transportation request.":"Commencez une demande de transport à Washington, DC.",
   "Start an Annapolis or Anne Arundel transportation request.":"Commencez une demande de transport à Annapolis ou Anne Arundel.",
   "Start application":"Commencer la candidature",
   "Start Auto Log":"Démarrer l'enregistrement automatique",
   "Start booking":"Commencer la réservation",
   "Start odometer":"Compteur kilométrique de départ",
   "Start online or call our public main line to coordinate recurring treatment travel with one connected workflow.":"Commencez en ligne ou appelez notre ligne publique principale pour coordonner les déplacements pour traitements récurrents avec un seul processus connecté.",
   "Start online or call our team with the passenger's equipment and access details, and we will match the trip to it.":"Commencez en ligne ou appelez notre équipe avec les détails d'équipement et d'accès du passager, et nous adapterons le trajet en conséquence.",
   "Start online with the pickup, destination, and appointment time, or call our public main line and we will plan the trip with you.":"Commencez en ligne avec la prise en charge, la destination et l'heure du rendez-vous, ou appelez notre ligne publique principale et nous planifierons le trajet avec vous.",
   "Start online, then keep passengers, family members, and facilities aligned through one coordinated transportation workflow.":"Commencez en ligne, puis gardez les passagers, les membres de la famille et les établissements alignés grâce à un seul processus de transport coordonné.",
