   "Stretcher service supports passengers who cannot travel seated and need non-emergency transport aligned with clinical scheduling and safe transfer timing.":"Le service de civière accompagne les passagers qui ne peuvent pas voyager assis et ont besoin d'un transport non urgent aligné sur la planification clinique et des horaires de transfert sûrs.",
