   "Subject to applicable law and exceptions, you may ask whether Nexus processes your consumer health data, request access or correction, request deletion, withdraw consent for consent-based processing, or appeal a denied request. Some information may need to be retained to complete a trip, document a service, process a claim, protect safety, or satisfy legal obligations.":"Sous réserve de la loi applicable et des exceptions, vous pouvez demander si Nexus traite vos données de santé de consommateur, demander l'accès ou la correction, demander la suppression, retirer votre consentement pour un traitement fondé sur le consentement, ou faire appel d'une demande refusée. Certaines informations peuvent devoir être conservées pour effectuer un trajet, documenter un service, traiter une réclamation, protéger la sécurité ou satisfaire à des obligations légales.",
