   "Time pending":"Heure en attente",
   "Time-limited viewing":"Consultation limitée dans le temps",
   "Times above fares show driving. Round trips include both directions; waiting is shown separately.":"Les temps au-dessus des tarifs indiquent la conduite. Les allers-retours incluent les deux sens ; l’attente est affichée séparément.",
