   "to coordinate.":"pour coordonner.",
   "To help passengers and care teams make better decisions, Nexus publishes service pages by ride type and area with direct booking paths.":"Pour aider les passagers et les équipes soignantes à prendre de meilleures décisions, Nexus publie des pages de services par type de trajet et par zone avec des parcours de réservation directs.",
   "To report an accessibility barrier or request an alternative format, review our":"Pour signaler un obstacle d’accessibilité ou demander un format alternatif, consultez notre",
   "To request information in an alternative format, report an accessibility barrier, or receive help using the website, contact Nexus Medical Transit:":"Pour demander des informations dans un format alternatif, signaler un obstacle d’accessibilité ou obtenir de l’aide pour utiliser le site Web, contactez Nexus Medical Transit :",
   "To the extent permitted by law, digital services are provided on an “as available” basis. Nothing in these Terms limits rights or remedies that cannot legally be waived. Any limitation of liability, indemnification, arbitration, class-action waiver, or governing-law provision applicable to a particular contracted service will be stated in the controlling passenger, facility, payer, provider, or other written agreement.":"Dans la mesure permise par la loi, les services numériques sont fournis sur une base « tels que disponibles ». Rien dans les présentes Conditions ne limite les droits ou recours qui ne peuvent légalement faire l’objet d’une renonciation. Toute limitation de responsabilité, indemnisation, arbitrage, renonciation aux recours collectifs ou disposition relative au droit applicable à un service contractuel particulier sera énoncée dans l’accord écrit applicable au passager, à l’établissement, au payeur, au fournisseur ou autre accord écrit.",
   "to the other 46 contiguous states for trips planned in advance. Alaska, Hawaii, and international trips are not served.":"vers les 46 autres États contigus pour les trajets planifiés à l’avance. Alaska, Hawaii et les trajets internationaux ne sont pas desservis.",
