   "Use booking for trip details or call the main line for coordination support.":"Utilisez la réservation pour les détails du trajet ou appelez la ligne principale pour une assistance à la coordination.",
   "Use fictional contact details. All booking, driver, delay and handoff communications stay in the simulated demo inbox.":"Utilisez des coordonnées fictives. Toutes les communications de réservation, de chauffeur, de retard et de transfert restent dans la boîte de réception de démonstration simulée.",
   "Use Find Trip to try again.":"Utilisez Trouver un trajet pour réessayer.",
   "Use Nexus vehicle":"Utiliser un véhicule Nexus",
   "Use or disclose PHI only as permitted by contract or law and apply the minimum-necessary standard where required.":"N’utilisez ou ne divulguez les PHI que tel que permis par le contrat ou la loi et appliquez la norme du minimum nécessaire lorsque cela est requis.",
   "use strict":"use strict",
   "Use the access method assigned to you. Never share a password, facility account or patient verification details.":"Utilisez la méthode d’accès qui vous a été attribuée. Ne partagez jamais un mot de passe, un compte d’établissement ou des détails de vérification de patient.",
   "Use the main line at":"Utilisez la ligne principale au",
   "Use the main public line at":"Utilisez la ligne publique principale au",
   "Use the online booking flow or call our main line to align the ride, service level, and discharge timing.":"Utilisez le processus de réservation en ligne ou appelez notre ligne principale pour aligner le trajet, le niveau de service et l’heure de sortie.",
   "Use the ride date to look up the flight terminal. Confirm that the returned airport matches this trip stop.":"Utilisez la date du trajet pour rechercher le terminal de vol. Confirmez que l’aéroport renvoyé correspond à cet arrêt du trajet.",
   "Use the secure link from your invitation email to finish setting up your facility account.":"Utilisez le lien sécurisé de votre courriel d’invitation pour terminer la configuration de votre compte d’établissement.",
   "Use this page to call, email, and quickly navigate service-area pages for Maryland, Washington, DC, and Virginia transportation coordination — and to plan interstate, long-distance trips across the contiguous United States.":"Utilisez cette page pour appeler, envoyer un courriel et naviguer rapidement vers les pages des zones desservies pour la coordination des transports dans le Maryland, Washington, DC et la Virginie — et pour planifier des trajets inter-États et longue distance à travers les États-Unis contigus.",
   "Use this ride type":"Utiliser ce type de trajet",
   "Use your booking reference when completing payment. Billing status remains visible to the NEXUS ONE Billing module.":"Utilisez votre référence de réservation lors du paiement. Le statut de facturation reste visible pour le module de facturation NEXUS ONE.",
   "Use your driver username and password to see assigned trips and minimum necessary patient details.":"Utilisez votre nom d’utilisateur et votre mot de passe de chauffeur pour voir les trajets affectés et les détails du patient strictement nécessaires.",
   "Use your facility account number and password to view only your organizations rides.":"Utilisez votre numéro de compte d’établissement et votre mot de passe pour voir uniquement les trajets de votre organisation.",
   "Use your Nexus username and password for complete operational coordination access.":"Utilisez votre nom d’utilisateur et votre mot de passe Nexus pour un accès complet à la coordination opérationnelle.",
   "Used by Cost Analyzer to measure operating cost and profit.":"Utilisé par l’Analyseur de coûts pour mesurer le coût d’exploitation et le profit.",
