   "What else can I ask?":"Que puis-je demander d'autre ?",
   "What happens after you apply.":"Ce qui se passe après votre candidature.",
   "What if I'm not sure which vehicle we need?":"Et si je ne sais pas quel véhicule il nous faut ?",
   "what if it's Saturday":"et si c’est samedi",
   "What is non-emergency medical transportation?":"Qu'est-ce que le transport médical non urgent ?",
   "What is the best number to call?":"Quel est le meilleur numéro à appeler ?",
   "What kinds of trips can go long-distance?":"Quels types de trajets peuvent être longue distance ?",
   "What Nex can and can't do":"Ce que Nex peut et ne peut pas faire",
   "What number should DC passengers use?":"Quel numéro les passagers de DC doivent-ils utiliser ?",
   "What number should discharge teams use?":"Quel numéro les équipes de sortie doivent-elles utiliser ?",
   "What number should Maryland passengers use first?":"Quel numéro les passagers du Maryland doivent-ils utiliser en premier ?",
   "What number should Northern Virginia passengers use?":"Quel numéro les passagers du nord de la Virginie doivent-ils utiliser ?",
