   "Your driver is assigned and dispatch is preparing route movement.":"Votre chauffeur est affecté et la répartition prépare le déplacement de l'itinéraire.",
   "Your estimate is based on the selected ride, distance, and travel time.":"Votre estimation est basée sur le trajet sélectionné, la distance et le temps de trajet.",
