   "Your Nexus Medical Transit virtual assistant. Ask about services, coverage areas, booking, accessibility, and ride tracking. Nex retrieves answers from approved Nexus information and can help point you to the next step.":"Votre assistant virtuel Nexus Medical Transit. Posez des questions sur les services, les zones desservies, la réservation, l'accessibilité et le suivi des trajets. Nex récupère les réponses à partir des informations Nexus approuvées et peut vous aider à passer à l'étape suivante.",
   "Your password is managed by the Nexus production user directory.":"Votre mot de passe est géré par l'annuaire des utilisateurs de production Nexus.",
   "Your payment has been received in full.":"Votre paiement a été reçu intégralement.",
   "Your payment is still being confirmed. Refresh this page to check its status. Please do not pay again.":"Votre paiement est toujours en cours de confirmation. Actualisez cette page pour vérifier son statut. Veuillez ne pas payer à nouveau.",
   "Your phone":"Votre téléphone",
