   "button compact secondary":"button compact secondary",
   "button secondary":"button secondary",
   "By providing a mobile number through a disclosed Nexus booking or enrollment flow, you agree to receive transactional booking and ride updates. Message frequency varies and message and data rates may apply. Reply STOP to end texts and HELP for assistance. Stopping messages may limit real-time trip updates but does not cancel a scheduled trip. Call Customer Service to change communication preferences or cancel transportation. Consent is not a condition of purchase.":"Al proporcionar un número de móvil a través de un flujo de reserva o inscripción de Nexus divulgado, acepta recibir actualizaciones transaccionales de reserva y viaje. La frecuencia de los mensajes varía y pueden aplicarse tarifas de mensajes y datos. Responda STOP para finalizar los textos y HELP para obtener asistencia. Detener los mensajes puede limitar las actualizaciones del viaje en tiempo real, pero no cancela un viaje programado. Llame a Atención al Cliente para cambiar sus preferencias de comunicación o cancelar el transporte. El consentimiento no es una condición de compra.",
   "By providing your number and continuing, you agree to receive transactional booking and ride texts from Nexus Medical Transit, including one reminder if an unfinished booking is inactive for five minutes. Message frequency varies. Message and data rates may apply. Reply HELP for help or STOP to opt out. Consent is not a condition of purchase.":"Al proporcionar su número y continuar, acepta recibir textos transaccionales de reserva y viaje de Nexus Medical Transit, incluido un recordatorio si una reserva sin terminar permanece inactiva durante cinco minutos. La frecuencia de los mensajes varía. Pueden aplicarse tarifas de mensajes y datos. Responda HELP para obtener ayuda o STOP para cancelar la suscripción. El consentimiento no es una condición de compra.",
   "By submitting, you authorize Nexus Medical Transit to contact you about employment opportunities. Information is used for recruiting and hiring purposes.":"Al enviar, autoriza a Nexus Medical Transit a contactarlo sobre oportunidades de empleo. La información se utiliza con fines de reclutamiento y contratación.",
   "calc(10% - 12px)":"calc(10% - 12px)",
   "Calculate itemized estimate":"Calcular la estimación detallada",
   "Calculate the route to check travel time and traffic between stops.":"Calcule la ruta para verificar el tiempo de viaje y el tráfico entre paradas.",
   "Calculated from arrival to the next pickup.":"Calculado desde la llegada hasta la siguiente recogida.",
   "Calculated from the route and appointment time.":"Calculado a partir de la ruta y la hora de la cita.",
   "Calculated to arrive by your required time.":"Calculado para llegar a la hora requerida.",
   "Calculated to get you to your appointment on time.":"Calculado para llevarlo a su cita a tiempo.",
   "Calculating prices...":"Calculando precios...",
