   "Common long-distance trips include appointments at hospitals and specialists in other states, hospital discharge rides to family in another state, interfacility transfers, and trips that start and end outside the local region entirely. If the care your passenger needs is in another state, we can plan the ride around it.":"Los viajes de larga distancia comunes incluyen citas en hospitales y con especialistas en otros estados, viajes de alta hospitalaria a la familia en otro estado, traslados entre centros, y viajes que comienzan y terminan completamente fuera de la región local. Si la atención que su pasajero necesita está en otro estado, podemos planificar el viaje en función de ello.",
