   "Communications and safety":"Comunicaciones y seguridad",
   "Communications may include booking confirmations, driver or vehicle details, pickup status, delays, cancellations, recurring-trip reminders, account security, payment, support, and safety information. Message frequency varies. Carrier message and data rates may apply.":"Las comunicaciones pueden incluir confirmaciones de reserva, detalles del conductor o del vehículo, estado de la recogida, retrasos, cancelaciones, recordatorios de viajes recurrentes, seguridad de la cuenta, pago, asistencia e información de seguridad. La frecuencia de los mensajes varía. Pueden aplicarse tarifas de mensajes y datos del operador.",
