   "dates booked":"fechas reservadas",
   "Day-to-day service covers Maryland, Washington, DC, and Virginia. Nexus also provides interstate and long-distance transportation to the other 46 contiguous states for trips planned in advance — Alaska, Hawaii, and international trips are not served. See our Maryland, DC, and Northern Virginia pages for local detail, or our":"El servicio diario cubre Maryland, Washington, DC y Virginia. Nexus también ofrece transporte interestatal y de larga distancia a los otros 46 estados contiguos para viajes planificados con anticipación — Alaska, Hawaii y los viajes internacionales no están cubiertos. Consulte nuestras páginas de Maryland, DC y el norte de Virginia para obtener detalles locales, o nuestro",
