   "Dialysis Center":"Centro de diálisis",
   "Dialysis centers, rehabilitation, and skilled nursing facilities":"Centros de diálisis, rehabilitación y centros de enfermería especializada",
   "Dialysis often starts early. Many treatment shifts begin in the early morning, so Nexus builds early morning pickups into recurring schedules in advance — timed to your center's start time, so you arrive settled rather than rushed. Regular hours are Monday–Friday, 7 AM–7 PM, and earlier pickups are arranged by appointment when your schedule is set up.":"La diálisis suele comenzar temprano. Muchos turnos de tratamiento comienzan temprano por la mañana, por lo que Nexus incorpora recogidas temprano por la mañana en los horarios recurrentes con anticipación, programadas según la hora de inicio de su centro, para que llegue tranquilo en lugar de apresurado. El horario habitual es de lunes a viernes, de 7 a. m. a 7 p. m., y las recogidas más tempranas se organizan con cita previa cuando se configura su horario.",
   "Dialysis several times a week":"Diálisis varias veces por semana",
   "Dialysis transportation":"Transporte para diálisis",
   "Dialysis Transportation | Nexus Medical Transit":"Transporte para diálisis | Nexus Medical Transit",
   "Dialysis transportation is coordinated across Maryland, Washington, DC, and Northern Virginia based on trip details and operational availability. For longer trips, Nexus also provides interstate and long-distance transportation across the contiguous United States, scheduled in advance.":"El transporte para diálisis se coordina en Maryland, Washington, DC y el norte de Virginia según los detalles del viaje y la disponibilidad operativa. Para viajes más largos, Nexus también ofrece transporte interestatal y de larga distancia en todo el territorio continental de Estados Unidos, programado con anticipación.",
   "Dialysis transportation page":"Página de transporte para diálisis",
   "Dialysis transportation with dependable scheduling and repeat-trip coordination.":"Transporte para diálisis con programación confiable y coordinación de viajes repetidos.",
   "Discharge and transfer coordination for Annapolis-area facilities, with LiveCare tracking for families from pickup to arrival.":"Coordinación de altas y traslados para centros de la zona de Annapolis, con seguimiento LiveCare para las familias desde la recogida hasta la llegada.",
   "Discharge coordination":"Coordinación de altas",
   "Discharge home for patients who cannot ride seated":"Alta a domicilio para pacientes que no pueden viajar sentados",
   "Discharge planning and return-home transportation":"Planificación del alta y transporte de regreso a casa",
   "Discharge travel works best when pickup timing, passenger mobility, destination, and handoff are coordinated clearly before release.":"El viaje de alta funciona mejor cuando el horario de recogida, la movilidad del pasajero, el destino y la entrega se coordinan claramente antes del alta.",
