   "Do not enter patient names, diagnoses, medical records, payment details, or other sensitive personal information here. Questions are sent to the Nexus assistant service to generate a response. The public assistant uses a small amount of conversation history kept in this page's memory to understand follow-up questions. Reloading or closing the page clears it; this page does not save chat history to browser storage.":"No ingrese aquí nombres de pacientes, diagnósticos, historiales médicos, detalles de pago ni otra información personal sensible. Las preguntas se envían al servicio de asistencia de Nexus para generar una respuesta. El asistente público utiliza una pequeña cantidad del historial de conversación guardado en la memoria de esta página para comprender las preguntas de seguimiento. Volver a cargar o cerrar la página lo borra; esta página no guarda el historial de chat en el almacenamiento del navegador.",
   "Do not fill this out:":"No complete esto:",
   "Do not send Social Security or financial information.":"No envíe información del Seguro Social ni información financiera.",
   "Do not upload driver licenses, government IDs, insurance certificates, or patient records here. Nexus will request supporting credentials through its secure verification process.":"No cargue aquí licencias de conducir, identificaciones gubernamentales, certificados de seguro ni historiales de pacientes. Nexus solicitará las credenciales de respaldo a través de su proceso de verificación seguro.",
   "Do not use a privacy request or email to seek urgent transportation or medical assistance. For a medical emergency, call 911. For an active trip, call Customer Service.":"No utilice una solicitud de privacidad ni un correo electrónico para buscar transporte urgente o asistencia médica. En caso de emergencia médica, llame al 911. Para un viaje activo, llame a Servicio al Cliente.",
   "Do you offer bariatric transportation near me?":"¿Ofrece transporte bariátrico cerca de mí?",
   "Do you offer early morning pickups for surgery, dialysis, or early appointments?":"¿Ofrece recogidas temprano por la mañana para cirugía, diálisis o citas tempranas?",
