   "Draft AI recommendations are not published as approved business facts. Mark them reviewed after fact-checking or dismiss them; neither action changes Nex's knowledge base.":"Las recomendaciones de IA en borrador no se publican como hechos comerciales aprobados. Márquelas como revisadas después de verificar los datos o descártelas; ninguna de las dos acciones cambia la base de conocimientos de Nex.",
   "Draft answers from reviewed recommendations. Every claim must be checked against the selected Nexus website page. Approval does not publish the answer; publication requires a separate reviewed GitHub change.":"Respuestas en borrador a partir de recomendaciones revisadas. Cada afirmación debe comprobarse con la página seleccionada del sitio web de Nexus. La aprobación no publica la respuesta; la publicación requiere un cambio de GitHub separado y revisado.",
