   "Enter coupon code":"Ingrese el código del cupón",
   "Enter each appointment time. Pickup and waiting at each stop are calculated from the next appointment. We include travel, traffic, and passenger assistance to check whether one driver can make every appointment.":"Ingrese cada hora de cita. La recogida y la espera en cada parada se calculan a partir de la siguiente cita. Incluimos el viaje, el tráfico y la asistencia al pasajero para comprobar si un solo conductor puede cumplir todas las citas.",
