   "Hospital Discharge Transportation | Nexus Medical Transit":"Transporte para alta hospitalaria | Nexus Medical Transit",
   "Hospital discharge transportation is coordinated across Maryland, Washington, DC, and Northern Virginia based on facility location, passenger needs, and route availability. For longer trips — including discharge to family in another state — Nexus also provides interstate and long-distance transportation across the contiguous United States, scheduled in advance.":"El transporte para alta hospitalaria se coordina en Maryland, Washington, DC y el norte de Virginia según la ubicación del centro, las necesidades del pasajero y la disponibilidad de rutas. Para viajes más largos, incluido el alta a la familia en otro estado, Nexus también ofrece transporte interestatal y de larga distancia en todo el territorio continental de Estados Unidos, programado con anticipación.",
   "Hospital discharge transportation planned around the passenger, caregiver, and release timeline.":"Transporte para alta hospitalaria planificado en función del pasajero, el cuidador y el cronograma de alta.",
