   "I am legally authorized to work in the United States. *":"Estoy legalmente autorizado a trabajar en los Estados Unidos. *",
   "I can show you how to use the app and explain Nexus when you want more detail.":"Puedo mostrarle cómo usar la aplicación y explicarle Nexus cuando quiera más detalles.",
   "I can work out a rough estimate right here — no need to open the booking app first. I just need a few details. (Availability itself is confirmed when you book.)":"Puedo calcular una estimación aproximada aquí mismo; no es necesario abrir primero la aplicación de reservas. Solo necesito algunos datos. (La disponibilidad en sí se confirma al reservar).",
   "I can’t reach the assistant right now. Please call us at":"No puedo comunicarme con el asistente en este momento. Llámenos al",
   "I certify that the information provided is true and complete to the best of my knowledge. I understand that false statements may disqualify me from consideration or employment. *":"Certifico que la información proporcionada es verdadera y completa según mi leal saber y entender. Entiendo que las declaraciones falsas pueden descalificarme de la consideración o del empleo. *",
