   "Identify passengers and users, coordinate trips, communicate, prevent fraud":"Identificar a pasajeros y usuarios, coordinar viajes, comunicarse, prevenir el fraude",
   "Identify transportation barriers early, coordinate the right intervention, and verify whether patients reach care.":"Identificar temprano las barreras de transporte, coordinar la intervención adecuada y verificar si los pacientes llegan a la atención.",
   "Identity and contact":"Identidad y contacto",
   "If an account exists, a reset link has been sent.":"Si existe una cuenta, se ha enviado un enlace de restablecimiento.",
   "If no report arrives for more than 15 minutes, monitoring is marked stale. If the database or hosting platform is down, this monitor may also be unavailable.":"Si no llega ningún informe durante más de 15 minutos, la supervisión se marca como desactualizada. Si la base de datos o la plataforma de alojamiento está caída, este monitor también puede no estar disponible.",
   "If you are experiencing a medical emergency, call 911 immediately.":"Si está experimentando una emergencia médica, llame al 911 de inmediato.",
   "If your health plan, provider, facility, or broker arranged the transportation, it may be the best first contact for a HIPAA access, amendment, restriction, or accounting request. Nexus will route or support requests as required. Verification of identity and authority may be required before information is released.":"Si su plan de salud, proveedor, centro o intermediario organizó el transporte, puede ser el mejor primer contacto para una solicitud de acceso, enmienda, restricción o rendición de cuentas de HIPAA. Nexus derivará o apoyará las solicitudes según sea necesario. Es posible que se requiera verificar la identidad y la autoridad antes de divulgar información.",
