   "Inferences reasonably necessary to select or coordinate an appropriate transportation service.":"Inferencias razonablemente necesarias para seleccionar o coordinar un servicio de transporte adecuado.",
   "Information another authorized person provides when arranging a trip.":"Información que otra persona autorizada proporciona al organizar un viaje.",
   "Information is retained for as long as reasonably necessary for transportation, safety, billing, legal, contractual, audit, dispute-resolution, and recordkeeping purposes. Retention varies by record type and applicable requirements. When information is no longer required, Nexus takes reasonable steps to delete, destroy, or de-identify it.":"La información se conserva durante el tiempo razonablemente necesario para fines de transporte, seguridad, facturación, legales, contractuales, de auditoría, de resolución de disputas y de mantenimiento de registros. La conservación varía según el tipo de registro y los requisitos aplicables. Cuando la información ya no es necesaria, Nexus toma medidas razonables para eliminarla, destruirla o desidentificarla.",
   "Information may come directly from you or from an authorized caregiver, facility, healthcare provider, health plan, broker, government program, transportation provider, driver, payment processor, communications provider, or other party involved in arranging or delivering a trip.":"La información puede provenir directamente de usted o de un cuidador autorizado, un centro, un proveedor de atención médica, un plan de salud, un intermediario, un programa gubernamental, un proveedor de transporte, un conductor, un procesador de pagos, un proveedor de comunicaciones u otra parte involucrada en organizar o realizar un viaje.",
