   "Issues appear here after two failed checks and clear when a check passes. Acknowledging an issue records that it has been seen; it does not repair it. No code or production records are changed. AI recommendations require an API connection and human review.":"Los problemas aparecen aquí después de dos verificaciones fallidas y desaparecen cuando una verificación se supera. Reconocer un problema registra que se ha visto; no lo repara. No se cambia ningún código ni registro de producción. Las recomendaciones de IA requieren una conexión API y revisión humana.",
   "Jan":"Ene",
