   "Johns Hopkins Health Plans":"Johns Hopkins Health Plans",
   "Join a team that connects patients with essential care across Maryland, Washington, DC, and Northern Virginia. We value safety, compassion, accountability, and respect in every role.":"Únase a un equipo que conecta a los pacientes con atención esencial en Maryland, Washington, DC y el norte de Virginia. Valoramos la seguridad, la compasión, la responsabilidad y el respeto en cada puesto.",
