   "Kaiser Permanente":"Kaiser Permanente",
   "Keep credentials confidential, use only the access assigned to you, and notify Nexus of suspected unauthorized access. Facility, driver, dispatcher, billing, and administrative portals may only be used for authorized business purposes. Users may not scrape data, probe security, disrupt service, impersonate another person, or access records without a legitimate need.":"Mantenga sus credenciales confidenciales, use solo el acceso que se le ha asignado e informe a Nexus de cualquier sospecha de acceso no autorizado. Los portales de centros, conductores, despacho, facturación y administración solo pueden utilizarse con fines comerciales autorizados. Los usuarios no pueden extraer datos, probar la seguridad, interrumpir el servicio, suplantar a otra persona ni acceder a registros sin una necesidad legítima.",
   "Keep current schedule":"Mantener el horario actual",
