   "MANUAL":"MANUAL",
   "Manual override":"Anulación manual",
   "Many surgeries, dialysis treatments, and clinic appointments start early — often before regular hours. Nexus schedules early morning pickups in advance, timed around your check-in or treatment time, so the right vehicle and crew are matched to the trip before the day begins. Our regular hours are Monday–Friday, 7 AM–7 PM, and early pickups are arranged by appointment when you book ahead.":"Muchas cirugías, tratamientos de diálisis y citas en clínicas comienzan temprano, a menudo antes del horario regular. Nexus programa con antelación las recogidas temprano en la mañana, según su hora de registro o tratamiento, para que el vehículo y el equipo adecuados se asignen al viaje antes de que comience el día. Nuestro horario regular es de lunes a viernes, de 7 a. m. a 7 p. m., y las recogidas tempranas se organizan con cita previa cuando reserva con antelación.",
