   "Mock Trips":"Viajes simulados",
   "Mock trips and incomplete driving or GPS records are excluded. Thirty separate trips is an initial review target; route mix, traffic and patient needs still need comparison. This report does not change any speed or fare setting.":"Se excluyen los viajes simulados y los registros de conducción o GPS incompletos. Treinta viajes separados es un objetivo inicial de revisión; aún deben compararse la combinación de rutas, el tráfico y las necesidades de los pacientes. Este informe no cambia ninguna configuración de velocidad ni de tarifa.",
   "Mock trips appear in Trip Management under Mock Trips. They do not request transport or collect payment.":"Los viajes simulados aparecen en Gestión de viajes, en Viajes simulados. No solicitan transporte ni cobran pagos.",
