   "No. For emergencies, call 911. This page is for planned, non-emergency medical transportation.":"No. Para emergencias, llame al 911. Esta página es para transporte médico planificado y no urgente.",
   "No. Interstate service covers the 48 contiguous United States. Alaska, Hawaii, and anywhere outside the United States are out of area — for a trip entirely outside the contiguous states, a medical transport provider local to that area is the right call.":"No. El servicio interestatal cubre los 48 estados contiguos de Estados Unidos. Alaska, Hawaii y cualquier lugar fuera de los Estados Unidos están fuera del área — para un viaje completamente fuera de los estados contiguos, un proveedor de transporte médico local de esa área es la opción adecuada.",
   "No. Nexus provides planned, non-emergency ambulance transportation. For an emergency, call 911.":"No. Nexus ofrece transporte en ambulancia planificado y no urgente. Para una emergencia, llame al 911.",
