   "of the Netlify environment variable that holds the value — names must start with KEYMARK_. The value itself stays in Netlify and is never stored in KeyMark. Saving with a name that already exists updates that connection. A new connection starts as “Configuration required” and becomes Active after its first successful test.":"de la variable de entorno de Netlify que contiene el valor — los nombres deben empezar por KEYMARK_. El valor en sí permanece en Netlify y nunca se almacena en KeyMark. Guardar con un nombre que ya existe actualiza esa conexión. Una nueva conexión comienza como “Configuración requerida” y se vuelve Active después de su primera prueba exitosa.",
