   "One identity can serve several roles. Classifications and business relationships do not grant account access. Sign-in accounts are managed separately, in each person's Account & access section — this page is the one place administrators manage people and their accounts.":"Una identidad puede cumplir varias funciones. Las clasificaciones y las relaciones comerciales no otorgan acceso a la cuenta. Las cuentas de inicio de sesión se gestionan por separado, en la sección Cuenta y acceso de cada persona — esta página es el único lugar donde los administradores gestionan a las personas y sus cuentas.",
