   "Price depends on the trip itself — distance, ride type, required personnel and equipment, and timing — so there is no set fare. Book online at":"El precio depende del viaje en sí — distancia, tipo de viaje, personal y equipo requeridos, y horario — por lo que no hay una tarifa fija. Reserve en línea en",
   "Price estimates are based on information available when quoted and may change if mileage, wait time, tolls, service level, required personnel, equipment, or trip conditions change. Coverage or authorization by a health plan, government program, broker, facility, or other payer is not guaranteed. The responsible party remains responsible for charges not covered or authorized, to the extent permitted by law and contract.":"Las estimaciones de precios se basan en la información disponible al momento de la cotización y pueden cambiar si cambian el kilometraje, el tiempo de espera, los peajes, el nivel de servicio, el personal requerido, el equipo o las condiciones del viaje. No se garantiza la cobertura ni la autorización por parte de un plan de salud, un programa gubernamental, un intermediario, un centro u otro pagador. La parte responsable sigue siendo responsable de los cargos no cubiertos ni autorizados, en la medida permitida por la ley y el contrato.",
