   "Protocol *":"Protocolo *",
   "Provide accurate passenger, pickup, destination, appointment, contact, mobility, equipment, assistance, and payer information.":"Proporcione información exacta sobre el pasajero, la recogida, el destino, la cita, el contacto, la movilidad, el equipo, la asistencia y el pagador.",
   "Provide accurate trip and mobility information, use the service safely and lawfully, and contact us promptly when plans change. Nexus coordinates transportation; availability and arrival times can be affected by traffic, weather, clinical discharge timing, and other circumstances.":"Proporcione información exacta sobre el viaje y la movilidad, utilice el servicio de forma segura y legal, y contáctenos de inmediato cuando cambien los planes. Nexus coordina el transporte; la disponibilidad y las horas de llegada pueden verse afectadas por el tráfico, el clima, el momento del alta clínica y otras circunstancias.",
   "Provide safe, courteous transportation while completing vehicle checks, trip documentation, and patient handoffs.":"Proporcione un transporte seguro y cortés mientras completa las revisiones del vehículo, la documentación del viaje y las entregas de pacientes.",
   "Provide support, document instructions, investigate incidents and improve quality":"Brindar apoyo, documentar instrucciones, investigar incidentes y mejorar la calidad",
   "Provider:":"Proveedor:",
   "Public addresses are used for fictional trips only. Service eligibility, appointment availability and transport timings have not been confirmed.":"Las direcciones públicas se utilizan solo para viajes ficticios. No se han confirmado la elegibilidad para el servicio, la disponibilidad de citas ni los horarios de transporte.",
   "Public network overview":"Resumen de la red pública",
   "Public service areas":"Áreas de servicio públicas",
   "Public service pages, coordinated booking, and Livecare support keep transportation details visible and aligned.":"Las páginas de servicio públicas, la reserva coordinada y el apoyo de Livecare mantienen los detalles del transporte visibles y alineados.",
   "Public service-area pages":"Páginas de áreas de servicio públicas",
   "Public transportation resources":"Recursos de transporte público",
   "Public website checks, approved media availability, anonymous knowledge-gap trends and suggested changes. No private conversations or patient data are recorded here. All publishing and consequential operations still require authorized approval.":"Verificaciones del sitio web público, disponibilidad de medios aprobados, tendencias anónimas de brechas de conocimiento y cambios sugeridos. Aquí no se registran conversaciones privadas ni datos de pacientes. Toda publicación y operación importante sigue requiriendo aprobación autorizada.",
   "Publish an open shift":"Publicar un turno abierto",
   "Publish open shifts and connect your schedule with available drivers.":"Publique turnos abiertos y conecte su horario con los conductores disponibles.",
   "Publish openings and review driver requests using your existing Dispatch access.":"Publique las vacantes y revise las solicitudes de los conductores utilizando su acceso actual a Despacho.",
   "Publish shift →":"Publicar turno →",
   "Publishing: export an approved entry, submit the change to the version-controlled Nex approved-knowledge JSON, run tests, and merge the GitHub pull request. No automatic publication or silent edits.":"Publicación: exporte una entrada aprobada, envíe el cambio al JSON de conocimientos aprobados de Nex con control de versiones, ejecute las pruebas y fusione la solicitud de incorporación de cambios de GitHub. Sin publicación automática ni ediciones silenciosas.",
