   "Review trip":"Revisar viaje",
   "Review your phone number and email.":"Revise su número de teléfono y correo electrónico.",
   "Review your shift summary before signing out. This data is submitted to Dispatch and Fleet.":"Revise el resumen de su turno antes de cerrar sesión. Estos datos se envían a Despacho y Flota.",
   "Review-only suggestions based on anonymous aggregate counts. Nothing will be added to the knowledge base automatically. A minimum of three questions is required.":"Sugerencias de solo revisión basadas en conteos agregados anónimos. Nada se agregará automáticamente a la base de conocimientos. Se requiere un mínimo de tres preguntas.",
   "Reviewed October 2026. Recent research identifies road surface, suspension and smooth vehicle movement as factors in patient comfort; it does not establish fixed mph averages for each medical transport service. Wheelchair’s 10 mph deduction is a Nexus assumption. Securement, assisted loading and clinical handoff need their own time allowances.":"Revisado en octubre de 2026. Investigaciones recientes identifican la superficie de la carretera, la suspensión y el movimiento suave del vehículo como factores en la comodidad del paciente; no establecen promedios fijos en mph para cada servicio de transporte médico. La deducción de 10 mph para la silla de ruedas es una suposición de Nexus. La sujeción, la carga asistida y la entrega clínica necesitan sus propios tiempos asignados.",
