   "Schedule premium: Saturday and Sunday use the weekend rate; actual and observed federal holidays use the holiday rate. Weekday hours are 7:00 AM–7:00 PM. Each passenger leg receives one applicable premium on base fare, excess passenger mileage, fuel and traffic charges. Weekend takes priority, then holiday, then after hours. Waiting and empty miles are calculated separately.":"Recargo de horario: los sábados y domingos usan la tarifa de fin de semana; los días festivos federales reales y observados usan la tarifa de día festivo. El horario entre semana es de 7:00 AM–7:00 PM. Cada tramo de pasajero recibe un recargo aplicable sobre la tarifa base, el millaje excedente de pasajero, los cargos por combustible y tráfico. El fin de semana tiene prioridad, luego el día festivo, luego el horario fuera de horas. La espera y las millas en vacío se calculan por separado.",
   "Schedule preventive maintenance outside dialysis peak hours.":"Programe el mantenimiento preventivo fuera de las horas pico de diálisis.",
