   "Service area: Maryland, Washington, DC, and Virginia (local region), plus interstate and long-distance trips across the contiguous United States, planned in advance. Alaska, Hawaii, and international trips are not served.":"Área de servicio: Maryland, Washington, DC y Virginia (región local), además de viajes interestatales y de larga distancia en todo el territorio continental de Estados Unidos, planificados con anticipación. No se ofrece servicio a Alaska, Hawaii ni viajes internacionales.",
