   "Service pages by ride type can help clarify the best booking path before you submit a request.":"Las páginas de servicios por tipo de viaje pueden ayudar a aclarar la mejor ruta de reserva antes de enviar una solicitud.",
   "Service policy matrix":"Matriz de políticas de servicio",
   "Service pricing and fare matrix governance.":"Gobernanza de precios de servicios y de la matriz de tarifas.",
   "Service reductions apply to a cruising-speed ceiling. With a 65 mph baseline, wheelchair uses 55 mph, stretcher 45 mph, ambulance services 40 mph and Bariatric 30 mph. Google city and traffic times remain the minimum estimate; reductions are not subtracted from slow city averages. These are Nexus planning assumptions.":"Las reducciones de servicio se aplican a un límite de velocidad de crucero. Con una base de 65 mph, la silla de ruedas usa 55 mph, la camilla 45 mph, los servicios de ambulancia 40 mph y el bariátrico 30 mph. Los tiempos de Google en ciudad y tráfico siguen siendo la estimación mínima; las reducciones no se restan de los promedios lentos en ciudad. Estas son suposiciones de planificación de Nexus.",
