   "Some selected dates could not be booked. Check the booking message above for the dates that need attention.":"Algunas fechas seleccionadas no pudieron reservarse. Consulte el mensaje de reserva anterior para ver las fechas que necesitan atención.",
   "Some trips do not fit inside one region. When a passenger needs care in another state — a specialist appointment, a hospital discharge to family, a transfer between facilities — Nexus Medical Transit plans the ride end to end: door-through-door support, the right vehicle and crew for the distance, and a pickup timed to the appointment. Day-to-day service runs locally in Maryland, Washington, DC, and Virginia; interstate trips cover the rest of the 48 contiguous states.":"Algunos viajes no se limitan a una sola región. Cuando un pasajero necesita atención en otro estado — una cita con un especialista, un alta hospitalaria hacia su familia, un traslado entre centros — Nexus Medical Transit planifica el viaje de principio a fin: asistencia de puerta a puerta, el vehículo y el equipo adecuados para la distancia, y una recogida programada según la cita. El servicio diario opera localmente en Maryland, Washington, DC, y Virginia; los viajes interestatales cubren el resto de los 48 estados contiguos.",
   "Some trips, payments, maps, communications, or benefits may involve independent transportation providers or technology and payment vendors. Their services may be governed by additional terms. Nexus remains responsible for its own obligations but does not control every third party's independent acts.":"Algunos viajes, pagos, mapas, comunicaciones o beneficios pueden involucrar a proveedores de transporte independientes o proveedores de tecnología y pagos. Sus servicios pueden estar sujetos a términos adicionales. Nexus sigue siendo responsable de sus propias obligaciones, pero no controla los actos independientes de cada tercero.",
   "Something went wrong with that change — nothing was saved.":"Algo salió mal con ese cambio — no se guardó nada.",
