   "STAFF":"PERSONAL",
   "Staff / administrator sign-in":"Inicio de sesión del personal / administrador",
   "Staff members":"Miembros del personal",
   "Standard vehicles don't fit every passenger, and a ride that starts with \"will it fit?\" starts wrong. Nexus plans bariatric transportation in advance: the right vehicle, the right equipment — higher-capacity wheelchair securement or stretcher — and a crew briefed on the pickup location, so there are no surprises at the door. Tell us the passenger's mobility equipment and any access details (steps, doorways, elevator) when you book, and we match the trip to it.":"Los vehículos estándar no se adaptan a todos los pasajeros, y un viaje que empieza con «¿cabrá?» empieza mal. Nexus planifica el transporte bariátrico con anticipación: el vehículo adecuado, el equipo adecuado — sujeción para silla de ruedas de mayor capacidad o camilla — y un equipo informado sobre el lugar de recogida, para que no haya sorpresas en la puerta. Díganos el equipo de movilidad del pasajero y cualquier detalle de acceso (escalones, puertas, ascensor) al reservar, y adaptaremos el viaje a ello.",
   "Start / restart LiveCare demo":"Iniciar / reiniciar la demostración de LiveCare",
   "Start / restart morning":"Iniciar / reiniciar la mañana",
