   "Stretcher service supports passengers who cannot travel seated and need non-emergency transport aligned with clinical scheduling and safe transfer timing.":"El servicio de camilla apoya a los pasajeros que no pueden viajar sentados y necesitan transporte no urgente alineado con la programación clínica y horarios de traslado seguros.",
