   "Subject to applicable law and exceptions, you may ask whether Nexus processes your consumer health data, request access or correction, request deletion, withdraw consent for consent-based processing, or appeal a denied request. Some information may need to be retained to complete a trip, document a service, process a claim, protect safety, or satisfy legal obligations.":"Sujeto a la ley aplicable y a las excepciones, puede preguntar si Nexus procesa sus datos de salud como consumidor, solicitar acceso o corrección, solicitar la eliminación, retirar el consentimiento para el procesamiento basado en el consentimiento, o apelar una solicitud denegada. Es posible que deba conservarse cierta información para completar un viaje, documentar un servicio, procesar una reclamación, proteger la seguridad o cumplir obligaciones legales.",
