   "Tell Nexus about stairs, accessibility barriers, weight or equipment requirements, infection-control precautions, behavioral or safety concerns, and any escort requirement relevant to safe transportation.":"Informe a Nexus sobre escaleras, barreras de accesibilidad, requisitos de peso o equipamiento, precauciones de control de infecciones, preocupaciones de conducta o seguridad, y cualquier requisito de acompañante pertinente para un transporte seguro.",
   "Tell us about the work you want to do and the experience you bring.":"Cuéntenos sobre el trabajo que desea hacer y la experiencia que aporta.",
   "Tell us about your interests and experience. Fields marked with an asterisk are required. Do not include Social Security numbers, medical information, or other sensitive personal data.":"Cuéntenos sobre sus intereses y experiencia. Los campos marcados con un asterisco son obligatorios. No incluya números de Seguro Social, información médica ni otros datos personales sensibles.",
   "Tell us pickup, destination, appointment time, and mobility needs.":"Indíquenos la recogida, el destino, la hora de la cita y las necesidades de movilidad.",
