   "To help passengers and care teams make better decisions, Nexus publishes service pages by ride type and area with direct booking paths.":"Para ayudar a los pasajeros y equipos de atención a tomar mejores decisiones, Nexus publica páginas de servicios por tipo de viaje y zona con rutas directas de reserva.",
   "To report an accessibility barrier or request an alternative format, review our":"Para informar de una barrera de accesibilidad o solicitar un formato alternativo, consulte nuestro",
   "To request information in an alternative format, report an accessibility barrier, or receive help using the website, contact Nexus Medical Transit:":"Para solicitar información en un formato alternativo, informar de una barrera de accesibilidad o recibir ayuda para usar el sitio web, comuníquese con Nexus Medical Transit:",
   "To the extent permitted by law, digital services are provided on an “as available” basis. Nothing in these Terms limits rights or remedies that cannot legally be waived. Any limitation of liability, indemnification, arbitration, class-action waiver, or governing-law provision applicable to a particular contracted service will be stated in the controlling passenger, facility, payer, provider, or other written agreement.":"En la medida permitida por la ley, los servicios digitales se proporcionan «según disponibilidad». Nada en estos Términos limita los derechos o recursos a los que no se puede renunciar legalmente. Cualquier limitación de responsabilidad, indemnización, arbitraje, renuncia a demandas colectivas o disposición sobre la ley aplicable a un servicio contratado en particular se establecerá en el acuerdo escrito aplicable al pasajero, centro, pagador, proveedor u otro acuerdo escrito.",
