   "Upload the protected display version shown in the customer vault. Use a PNG or JPG up to 4 MB; the original source document remains outside the public website.":"Suba la versión de visualización protegida que se muestra en la bóveda del cliente. Use un PNG o JPG de hasta 4 MB; el documento fuente original permanece fuera del sitio web público.",
