   "Use a new version when linked content changes. External links use their provider’s access settings.":"Use una nueva versión cuando cambie el contenido vinculado. Los enlaces externos usan la configuración de acceso de su proveedor.",
   "Use a number authorized to receive ride updates.":"Use un número autorizado para recibir actualizaciones del viaje.",
   "Use authorized non-production credentials issued by Nexus administration.":"Use credenciales autorizadas que no sean de producción emitidas por la administración de Nexus.",
   "Use booking for trip details or call the main line for coordination support.":"Use la reserva para los detalles del viaje o llame a la línea principal para obtener apoyo de coordinación.",
   "Use fictional contact details. All booking, driver, delay and handoff communications stay in the simulated demo inbox.":"Use datos de contacto ficticios. Todas las comunicaciones de reserva, conductor, retraso y traspaso permanecen en la bandeja de entrada de demostración simulada.",
   "Use Find Trip to try again.":"Use Encontrar viaje para intentarlo de nuevo.",
   "Use Nexus vehicle":"Usar vehículo Nexus",
   "Use or disclose PHI only as permitted by contract or law and apply the minimum-necessary standard where required.":"Use o divulgue PHI solo según lo permitido por el contrato o la ley y aplique el estándar de mínimo necesario cuando sea requerido.",
   "use strict":"use strict",
   "Use the access method assigned to you. Never share a password, facility account or patient verification details.":"Use el método de acceso que se le ha asignado. Nunca comparta una contraseña, una cuenta de centro ni detalles de verificación del paciente.",
   "Use the main line at":"Use la línea principal al",
   "Use the main public line at":"Use la línea pública principal al",
   "Use the online booking flow or call our main line to align the ride, service level, and discharge timing.":"Use el proceso de reserva en línea o llame a nuestra línea principal para coordinar el viaje, el nivel de servicio y la hora del alta.",
   "Use the ride date to look up the flight terminal. Confirm that the returned airport matches this trip stop.":"Use la fecha del viaje para buscar la terminal de vuelo. Confirme que el aeropuerto devuelto coincide con esta parada del viaje.",
   "Use the secure link from your invitation email to finish setting up your facility account.":"Use el enlace seguro de su correo electrónico de invitación para terminar de configurar su cuenta de centro.",
   "Use this page to call, email, and quickly navigate service-area pages for Maryland, Washington, DC, and Virginia transportation coordination — and to plan interstate, long-distance trips across the contiguous United States.":"Use esta página para llamar, enviar un correo electrónico y navegar rápidamente a las páginas de áreas de servicio para la coordinación del transporte en Maryland, Washington, DC y Virginia — y para planificar viajes interestatales y de larga distancia en los Estados Unidos contiguos.",
   "Use this ride type":"Usar este tipo de viaje",
   "Use your booking reference when completing payment. Billing status remains visible to the NEXUS ONE Billing module.":"Use su referencia de reserva al completar el pago. El estado de facturación permanece visible para el módulo de facturación de NEXUS ONE.",
   "Use your driver username and password to see assigned trips and minimum necessary patient details.":"Use su nombre de usuario y contraseña de conductor para ver los viajes asignados y los detalles del paciente mínimamente necesarios.",
   "Use your facility account number and password to view only your organizations rides.":"Use su número de cuenta de centro y su contraseña para ver solo los viajes de su organización.",
   "Use your Nexus username and password for complete operational coordination access.":"Use su nombre de usuario y contraseña de Nexus para un acceso completo a la coordinación operativa.",
   "Used by Cost Analyzer to measure operating cost and profit.":"Utilizado por el Analizador de costos para medir el costo operativo y la ganancia.",
