   "Waiting time":"Tiempo de espera",
   "Waiting: calculated from arrival to the next pickup, including intermediate stops and the scheduled return. The first 15 minutes are free by default; remaining minutes round up to 15-minute blocks.":"Espera: calculada desde la llegada hasta la siguiente recogida, incluidas las paradas intermedias y el regreso programado. Los primeros 15 minutos son gratuitos por defecto; los minutos restantes se redondean a bloques de 15 minutos.",
