   "Watch:":"Ver:",
   "We are here to help with booking, ride status, accessibility, and facility coordination.":"Estamos aquí para ayudarle con la reserva, el estado del viaje, la accesibilidad y la coordinación con los centros.",
   "We can’t find that page":"No podemos encontrar esa página",
   "We collect and use consumer health data only as reasonably necessary to provide or maintain a requested transportation service, communicate about it, support safety and accessibility, obtain authorization or payment, investigate incidents, comply with law, and carry out other purposes with consent.":"Recopilamos y utilizamos los datos de salud del consumidor solo en la medida razonablemente necesaria para proporcionar o mantener un servicio de transporte solicitado, comunicarnos al respecto, apoyar la seguridad y la accesibilidad, obtener autorización o pago, investigar incidentes, cumplir con la ley y llevar a cabo otros propósitos con consentimiento.",
   "We communicate clearly, document accurately, and take responsibility for the work entrusted to us.":"Nos comunicamos con claridad, documentamos con precisión y asumimos la responsabilidad del trabajo que se nos confía.",
   "We coordinate stretcher transportation across Maryland, Washington, DC, and Northern Virginia based on route, clinical timing, and operational availability. For longer trips, Nexus also provides interstate and long-distance transportation across the contiguous United States, scheduled in advance.":"Coordinamos el transporte en camilla en Maryland, Washington, DC y el norte de Virginia según la ruta, el momento clínico y la disponibilidad operativa. Para viajes más largos, Nexus también proporciona transporte interestatal y de larga distancia en los Estados Unidos contiguos, programado con antelación.",
   "We coordinate wheelchair transportation across Maryland, Washington, DC, and Northern Virginia, subject to routing, availability, and trip details. For longer trips, Nexus also provides interstate and long-distance transportation across the contiguous United States, scheduled in advance.":"Coordinamos el transporte en silla de ruedas en Maryland, Washington, DC y el norte de Virginia, sujeto a la ruta, la disponibilidad y los detalles del viaje. Para viajes más largos, Nexus también proporciona transporte interestatal y de larga distancia en los Estados Unidos contiguos, programado con antelación.",
   "We could not calculate this schedule. Check the selected time.":"No pudimos calcular este horario. Compruebe la hora seleccionada.",
   "We could not prepare the fare. Check the addresses and appointment time, then try again.":"No pudimos preparar la tarifa. Compruebe las direcciones y la hora de la cita, luego inténtelo de nuevo.",
   "We could not recalculate this schedule. Please try again.":"No pudimos recalcular este horario. Por favor, inténtelo de nuevo.",
   "We follow procedures, speak up about risk, and never compromise patient or team safety.":"Seguimos los procedimientos, hablamos sobre los riesgos y nunca comprometemos la seguridad del paciente o del equipo.",
   "We help coordinate medical transportation for planned healthcare travel across Maryland based on passenger mobility, scheduling, and route needs.":"Ayudamos a coordinar el transporte médico para viajes de atención médica planificados en Maryland según la movilidad del pasajero, la programación y las necesidades de ruta.",
   "We match the vehicle and crew to the passenger and the distance.":"Adaptamos el vehículo y la tripulación al pasajero y a la distancia.",
   "We match the vehicle and crew to the passenger.":"Adaptamos el vehículo y la tripulación al pasajero.",
   "We may disclose the minimum information reasonably necessary to passengers and authorized representatives; facilities and care teams; health plans, brokers and payers; assigned drivers and transportation providers; payment, hosting, mapping, communications, support and security vendors; professional advisers; regulators and government authorities; and parties to a business transaction, subject to applicable confidentiality and legal requirements.":"Podemos divulgar la información mínima razonablemente necesaria a pasajeros y representantes autorizados; centros y equipos de atención; planes de salud, corredores y pagadores; conductores asignados y proveedores de transporte; proveedores de pago, alojamiento, cartografía, comunicaciones, apoyo y seguridad; asesores profesionales; reguladores y autoridades gubernamentales; y partes de una transacción comercial, sujeto a los requisitos de confidencialidad y legales aplicables.",
   "We serve Maryland, Washington, DC, and Virginia day to day, and we also provide interstate and long-distance transportation to the other 46 contiguous states for trips planned in advance. Call":"Servimos a Maryland, Washington, DC y Virginia a diario, y también proporcionamos transporte interestatal y de larga distancia a los otros 46 estados contiguos para viajes planificados con antelación. Llame",
   "We support planned non-emergency transportation through a single workflow that can be used by passengers, authorized caregivers, and facilities.":"Apoyamos el transporte no urgente planificado a través de un único flujo de trabajo que pueden utilizar pasajeros, cuidadores autorizados y centros.",
   "We treat every passenger, caregiver, partner, and colleague with patience, dignity, and respect.":"Tratamos a cada pasajero, cuidador, socio y colega con paciencia, dignidad y respeto.",
   "We use information to coordinate service, maintain safety, bill, communicate, and comply with law.":"Utilizamos la información para coordinar el servicio, mantener la seguridad, facturar, comunicarnos y cumplir con la ley.",
   "We will apply your saved needs as defaults for this ride.":"Aplicaremos sus necesidades guardadas como valores predeterminados para este viaje.",
   "We’re having trouble loading our website right now. Please try again in a moment. If you need help with a ride, our team is here by phone.":"Tenemos problemas para cargar nuestro sitio web en este momento. Por favor, inténtelo de nuevo en un momento. Si necesita ayuda con un viaje, nuestro equipo está disponible por teléfono.",
   "We’re temporarily unavailable":"Estamos temporalmente no disponibles",
   "Weak":"Débil",
   "Website updates are gathered for review; they are not automatically approved as answers. The Nexus team controls the approved knowledge catalog.":"Las actualizaciones del sitio web se recopilan para su revisión; no se aprueban automáticamente como respuestas. El equipo de Nexus controla el catálogo de conocimientos aprobado.",
