   "Your account":"Su cuenta",
   "Your administrator account can open every Nexus workspace. Patient and caregiver apps open in their respective experiences.":"Su cuenta de administrador puede abrir todos los espacios de trabajo de Nexus. Las aplicaciones de paciente y cuidador se abren en sus respectivas experiencias.",
   "Your authorization is active.":"Su autorización está activa.",
   "Your care, connected":"Su atención, conectada",
   "Your choices":"Sus opciones",
   "Your company policies and required training, together in one place.":"Las políticas de su empresa y la capacitación requerida, juntas en un solo lugar.",
   "Your current password":"Su contraseña actual",
   "Your demo is running":"Su demostración está en curso",
   "Your deposit has been received.":"Su depósito ha sido recibido.",
   "Your driver is approaching the pickup location.":"Su conductor se está acercando al lugar de recogida.",
   "Your driver is assigned and dispatch is preparing route movement.":"Su conductor está asignado y el despacho está preparando el movimiento de la ruta.",
   "Your estimate is based on the selected ride, distance, and travel time.":"Su estimación se basa en el viaje seleccionado, la distancia y el tiempo de viaje.",
