   "Your Nexus Medical Transit virtual assistant. Ask about services, coverage areas, booking, accessibility, and ride tracking. Nex retrieves answers from approved Nexus information and can help point you to the next step.":"Su asistente virtual de Nexus Medical Transit. Pregunte sobre servicios, áreas de cobertura, reservas, accesibilidad y seguimiento de viajes. Nex recupera respuestas de información aprobada de Nexus y puede ayudarle a pasar al siguiente paso.",
